{v:'VER',what:'cloud-feel-closecall-p2: the host marks a round in the hit word to player 2, and player 2 window pays CLOSE CALL once when that round reaches him inside his roll, nothing standing and nothing for a hit that is not a round',
 run:function(){
   if(!(window.__deploy&&window.__state&&window.__endRaid)) return 'SKIP: no raid here';
   var bad=[], g, p, own, E0=null, oK=keys, NK={}, k, h={state:'in',seat:0}, oSend=netSend, sent=[], st0, r;
   for(k in NET) NK[k]=NET[k];
   function hit(rd){ var m={t:'hit',dmg:20,kind:'sentry',name:'Sentry',x:p.x+5,y:p.y,seat:1}; if(rd) m.rd=1; return netHitTake(h,m); }
   function roll(){ p.ccT=undefined; p.roll=0; p.rollCd=0; p.iv=0; p.stam=100; tryRoll(); }
   try{
     __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __deploy({kit:[],safe:null,mapIx:0,seed:4242});
     g=__state(); if(!g||g.over||!g.player) return 'SKIP: no live raid';
     if(g.sim) return 'SKIP: the fixture raid is a sim raid';
     p=g.player; E0=g.ents;
     own=E0.filter(function(x){ return x.kind==='sentry'||x.kind==='crawler'||x.kind==='raider'; })[0];
     if(!own) return 'SKIP: staging: no enemy in the fixture raid to own the round';
     g.ents=[]; keys={}; g.career=true; g.cs={s:0,k:0}; g.arcade=false;
     // the host: a round into player 2's body goes out as a hit word marked as a round
     NET.on=true; NET.role='host'; NET.seat=0; NET.upSeed=g.seed>>>0; NET.peers=[{state:'in',seat:1}]; NET.up=[];
     netSend=function(q,m){ sent.push(m); return true; };
     r=netHitPlayer({net:true,seat:1,x:p.x,y:p.y,r:11},20,'sentry','Sentry',p.x,p.y,true);
     if(r!=='sent') return 'SKIP: staging: the host did not send the hit word ('+r+')';
     if(!(sent.length&&sent[0].t==='hit'&&sent[0].rd)) bad.push('the host hit word for a round does not say it is a round ('+JSON.stringify(sent[0])+')');
     netSend=oSend;
     // player 2 window
     NET.role='join'; NET.seat=1; NET.peers=[h]; NET.up=[]; NET.specG=null;
     roll(); if(!(p.roll>0&&p.iv>0)) return 'SKIP: staging: the roll did not start';
     st0=p.stam; r=hit(true);
     if(r!=='hit') return 'SKIP: staging: player 2 window did not take the hit word ('+r+')';
     if(g.cs.s!==CC_PTS) bad.push('player 2 in his roll: a round paid '+g.cs.s+' (want '+CC_PTS+')');
     if(!(p.stam>st0)) bad.push('player 2 in his roll: no stamina back ('+st0+' to '+p.stam+')');
     hit(true);
     if(g.cs.s>CC_PTS) bad.push('player 2: a second round in the same roll paid again ('+g.cs.s+')');
     g.cs.s=0; roll(); hit(false);
     if(g.cs.s!==0) bad.push('player 2: a hit that is not a round paid '+g.cs.s);
     g.cs.s=0; p.ccT=undefined; p.roll=0; p.rollCd=0; p.iv=0; p.hp=100; hit(true);
     if(g.cs.s!==0) bad.push('player 2 standing: a round paid '+g.cs.s);
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{
     try{ netSend=oSend; for(k in NET) if(!(k in NK)) delete NET[k]; for(k in NK) NET[k]=NK[k]; keys=oK; if(g&&E0) g.ents=E0; if(g) g.bullets.length=0; }catch(_h){}
     try{ __endRaid('abandon'); }catch(_e){}
     __topClear();
   }
   return bad.length?bad.join('; '):null; }},
